import{_ as o,o as r,c as l,a2 as s}from"./chunks/framework.DGvnA5EY.js";const n="/workbuddy-guide/assets/04-skill-vs-repetition.DsNsHuSI.png",a="/workbuddy-guide/assets/01-official-skill-market.BLRwED0h.png",i="/workbuddy-guide/assets/02-official-find-skill.PTyavE2s.png",b=JSON.parse('{"title":"第 5 章 加载一个真正用得上的 Skill","description":"> 内容来源：WorkBuddy 官方指南 · 技能（非官方整理，© 本指南作者，保留所有权利） 前四章你已经能跑通任务了。但你会发现一件事：每次都要重新交代一遍同样的流程。 这一章解决的正是这个问题——把一套做熟的操作装成 Skill，以后一句话就能调用。","frontmatter":{"title":"第 5 章 加载一个真正用得上的 Skill"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 5 章 加载一个真正用得上的 Skill/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 5 章 加载一个真正用得上的 Skill/index.md","lastUpdated":1791626462000}'),e={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 5 章 加载一个真正用得上的 Skill/index.md"};function d(g,t,p,h,k,u){return r(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="第-5-章-加载一个真正用得上的-skill" tabindex="-1">第 5 章 加载一个真正用得上的 Skill <a class="header-anchor" href="#第-5-章-加载一个真正用得上的-skill" aria-label="Permalink to &quot;第 5 章 加载一个真正用得上的 Skill&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 技能（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>前四章你已经能跑通任务了。但你会发现一件事：<strong>每次都要重新交代一遍同样的流程。</strong> 这一章解决的正是这个问题——把一套做熟的操作装成 Skill，以后一句话就能调用。</p><h2 id="一、skill-到底是什么-给-ai-装上-工具能力" tabindex="-1">一、Skill 到底是什么：给 AI 装上&quot;工具能力&quot; <a class="header-anchor" href="#一、skill-到底是什么-给-ai-装上-工具能力" aria-label="Permalink to &quot;一、Skill 到底是什么：给 AI 装上&quot;工具能力&quot;&quot;">​</a></h2><p><strong>技能（Skill）</strong> 为 WorkBuddy 增加「特定工具能力」——封装一组可执行的 脚本与工作流，让 AI 在你授权下完成具体动作。</p><p>听起来抽象，看几个实际的：</p><table tabindex="0"><thead><tr><th>Skill 能做的</th><th>相当于你不用再手动的</th></tr></thead><tbody><tr><td>发送邮件</td><td>每次手动写收件人、正文、点发送</td></tr><tr><td>订外卖</td><td>每次翻菜单、凑单、下单</td></tr><tr><td>查询股价</td><td>每次搜代码、看盘口</td></tr><tr><td>读写文件</td><td>每次手动打开、改名、保存</td></tr><tr><td>调用第三方 API</td><td>每次查文档、拼参数</td></tr></tbody></table><p><strong>一句话理解</strong>：Skill 是<strong>把&quot;怎么做&quot;固化下来</strong>，AI 照着执行就行。</p><p><img src="'+n+'" alt="左边每次都要重讲一遍流程，右边流程装成技能后按一下就行" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解技能的作用，与实际软件界面无关。</em></p><h2 id="二、页面概览-两个板块" tabindex="-1">二、页面概览：两个板块 <a class="header-anchor" href="#二、页面概览-两个板块" aria-label="Permalink to &quot;二、页面概览：两个板块&quot;">​</a></h2><p>技能板块分为两块：</p><table tabindex="0"><thead><tr><th>板块</th><th>内容</th></tr></thead><tbody><tr><td><strong>技能市场</strong></td><td>推荐技能，可按需一键安装</td></tr><tr><td><strong>已安装</strong></td><td>已安装的本地技能，可直接在对话中调用</td></tr></tbody></table><p><img src="'+a+'" alt="技能市场页面：顶部是专家·技能·连接器页签，下方是推荐技能卡片，每张右上角有 + 号" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>在左侧导航栏点**「专家·技能·连接器」<strong>，默认进入</strong>技能<strong>页签。 右上角的</strong>「添加技能」**按钮是安装入口，搜索框在右上角。</p><h2 id="三、安装技能-三条路" tabindex="-1">三、安装技能：三条路 <a class="header-anchor" href="#三、安装技能-三条路" aria-label="Permalink to &quot;三、安装技能：三条路&quot;">​</a></h2><p>点**「添加技能」**，会看到三个选项：</p><h3 id="方式一-上传技能-导入本地技能包" tabindex="-1">方式一：上传技能（导入本地技能包） <a class="header-anchor" href="#方式一-上传技能-导入本地技能包" aria-label="Permalink to &quot;方式一：上传技能（导入本地技能包）&quot;">​</a></h3><p>选<strong>上传技能</strong>，拖拽或点击<strong>选择文件</strong>，选中本地技能包即可完成导入。 导入后系统会自动完成配置，<strong>无需额外操作</strong>。</p><p><strong>什么情况用这个</strong>：你从别处拿到了别人做的 Skill 包（通常是 <code>.zip</code> 格式）。</p><h3 id="方式二-查找技能-让它帮你找" tabindex="-1">方式二：查找技能（让它帮你找） <a class="header-anchor" href="#方式二-查找技能-让它帮你找" aria-label="Permalink to &quot;方式二：查找技能（让它帮你找）&quot;">​</a></h3><p>选<strong>查找技能</strong>，<strong>输入任务描述</strong>，WorkBuddy 会自动查找相关技能。</p><p><img src="'+i+'" alt="查找技能：在对话框里描述需求，比如「请帮我查找并自动安装能「……」的skill」" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>这一条对新手最有用——<strong>你不用知道技能叫什么名字</strong>，描述你想要什么就行。 比如&quot;我要一个能把 Word 文档转成 PDF 的技能&quot;，它会给你候选。</p><h3 id="方式三-创建技能-让它帮你写一个" tabindex="-1">方式三：创建技能（让它帮你写一个） <a class="header-anchor" href="#方式三-创建技能-让它帮你写一个" aria-label="Permalink to &quot;方式三：创建技能（让它帮你写一个）&quot;">​</a></h3><p>选<strong>创建技能</strong>，同样输入任务描述，WorkBuddy 自动创建相关技能。</p><p><strong>什么情况用这个</strong>：市面上的技能都不满足你的独特需求，那就做一个。</p><h2 id="四、启用与关闭-不用卸载也能暂停" tabindex="-1">四、启用与关闭：不用卸载也能暂停 <a class="header-anchor" href="#四、启用与关闭-不用卸载也能暂停" aria-label="Permalink to &quot;四、启用与关闭：不用卸载也能暂停&quot;">​</a></h2><p>已安装的技能支持随时关闭或重新启用，<strong>无需卸载</strong>。</p><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td><strong>关闭</strong></td><td>技能仍保留在已安装列表，但<strong>不参与对话中的模型自动调用</strong></td></tr><tr><td><strong>重新开启</strong></td><td>立即恢复</td></tr><tr><td><strong>卸载</strong></td><td><strong>彻底删除</strong>技能及其开关记录</td></tr></tbody></table><p>官方特别强调了两个区别：</p><ul><li><strong>开关状态多端同步</strong> —— 启用/关闭记录在你的全局配置里，<strong>换设备也同步</strong></li><li><strong>不改动技能原文件</strong> —— 开关状态只记在配置里，<strong>不会修改技能包本身的 <code>SKILL.md</code> 文件</strong></li></ul><p><strong>官方建议</strong>：仅启用当前任务所需的技能，减少无关干扰并降低误调用概率。 技能装多了，它可能在你不需要的时候乱用。</p><h2 id="五、搜索与卸载" tabindex="-1">五、搜索与卸载 <a class="header-anchor" href="#五、搜索与卸载" aria-label="Permalink to &quot;五、搜索与卸载&quot;">​</a></h2><p><strong>搜索</strong>：技能较多时，用右上角搜索框输入关键词快速定位。</p><p><strong>卸载</strong>：需要在本机完全卸载时，选择<strong>卸载技能</strong>，也支持批量操作。</p><h2 id="六、一个坑-第三方-skill-可能要你的数据" tabindex="-1">六、一个坑：第三方 Skill 可能要你的数据 <a class="header-anchor" href="#六、一个坑-第三方-skill-可能要你的数据" aria-label="Permalink to &quot;六、一个坑：第三方 Skill 可能要你的数据&quot;">​</a></h2><p>官方在这一节写得很直白，建议你认真读：</p><blockquote><p>Skill 可能根据其能力与指令使用「信息收集与使用」中提到的任意数据， 也可能将你的输入内容发往第三方。<strong>建议优先使用官方推荐 Skill</strong>； 安装第三方 Skill 前请审慎校验来源、权限申请与脚本内容。</p></blockquote><p><strong>可能涉及哪些信息</strong>（视 Skill 而定）：账户身份信息、联系方式、用户输入内容、 使用行为日志、第三方平台凭证、本地文件读写、屏幕与输入控制权限。</p><p>实际范围<strong>以你安装与启用时授权的能力为准</strong>——同一个 Skill 在不同任务下 可能只用其中一部分。</p><h3 id="安全建议-官方原文要点" tabindex="-1">安全建议（官方原文要点） <a class="header-anchor" href="#安全建议-官方原文要点" aria-label="Permalink to &quot;安全建议（官方原文要点）&quot;">​</a></h3><ul><li>安装第三方 Skill 前，<strong>仔细查看其权限申请、来源说明与脚本内容</strong>，确认数据外发范围</li><li>Skill 调用第三方、修改本地文件、执行系统命令时，<strong>均以你本人身份执行</strong></li><li>涉及文件删除、批量写入、系统配置变更或资金类操作时，<strong>建议先在小范围验证再放大使用</strong></li></ul><h3 id="两个必须知道的提醒" tabindex="-1">两个必须知道的提醒 <a class="header-anchor" href="#两个必须知道的提醒" aria-label="Permalink to &quot;两个必须知道的提醒&quot;">​</a></h3><ul><li><strong>积分消耗</strong>：涉及复杂任务和复杂 Skill 时，积分消耗通常较高。</li><li><strong>第三方共享</strong>：部分 Skill 会把输入内容发往第三方（订外卖、查股票、发 IM 消息等）。</li></ul><h2 id="七、本章动手-装一个你下周就用得上的" tabindex="-1">七、本章动手：装一个你下周就用得上的 <a class="header-anchor" href="#七、本章动手-装一个你下周就用得上的" aria-label="Permalink to &quot;七、本章动手：装一个你下周就用得上的&quot;">​</a></h2><ol><li>点左侧**「专家·技能·连接器」→ 技能**</li><li>点右上角**「添加技能」→ 查找技能**</li><li>输入你真实想要的能力（比如&quot;把文档转成 PDF&quot;&quot;发邮件&quot;），看它给出哪些候选</li><li>装一个，先别装五个</li><li>回到对话区，试着让它用这个技能干一次活</li><li>完成后<strong>关掉</strong>它，观察是否影响别的任务</li></ol><h2 id="八、本章任务清单-做完就算过关" tabindex="-1">八、本章任务清单（做完就算过关） <a class="header-anchor" href="#八、本章任务清单-做完就算过关" aria-label="Permalink to &quot;八、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 说出 Skill 是什么（给 AI 装工具能力，把&quot;怎么做&quot;固化下来）</li><li>[ ] 知道技能板块的两个部分：技能市场、已安装</li><li>[ ] 用「查找技能」装过至少一个 Skill</li><li>[ ] 知道关闭和卸载的区别（关闭可恢复，卸载彻底删）</li><li>[ ] 装第三方 Skill 前会先看权限申请和来源</li><li>[ ] 只启用当前任务需要的技能，用完就关</li></ul><hr><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p>这一章术语密度很高，这里统一解释。</p></blockquote><p><strong>Skill（技能）</strong> 一个<strong>打包好的操作手册+执行脚本</strong>。它告诉 AI&quot;这类活该怎么做、按什么步骤做&quot;。 装上之后你不用再重复描述流程。类比：普通提示词是你每次口头交代一遍， Skill 是写成了 SOP 贴在墙上。</p><p><strong>工具能力</strong> Skill 赋予的<strong>具体动作能力</strong>，比如发邮件、查股票。区别于&quot;知识&quot;—— 它不是让 AI 知道得多，而是让 AI <strong>做得到</strong>。</p><p><strong>本地技能包</strong> 一个打包好的文件（通常是 <code>.zip</code>），里面装着这个 Skill 的全部内容。 别人做好了发给你，你就用「上传技能」导入。</p><p><strong>上传 / 查找 / 创建</strong> 安装 Skill 的三条路：</p><ul><li><strong>上传</strong> = 你已经有了包，导入</li><li><strong>查找</strong> = 你说需求，它帮你找现成的</li><li><strong>创建</strong> = 现成的都不行，让它帮你写一个</li></ul><p>新手用得最多的是<strong>查找</strong>——因为不用记名字。</p><p><strong>启用 / 关闭 / 卸载</strong> 三个层级的操作：</p><ul><li><strong>启用</strong> = 让它参与工作</li><li><strong>关闭</strong> = 暂停，文件还在，<strong>随时能开回来</strong></li><li><strong>卸载</strong> = 彻底删掉，<strong>找不回来了</strong></li></ul><p>只想让它暂时别用，用<strong>关闭</strong>，别用卸载。</p><p><strong>多端同步</strong> 在一台电脑上的设置，换到另一台自动生效。比如你在公司关了某个技能， 回家打开电脑也是关着的。</p><p><strong><code>SKILL.md</code></strong> Skill 包里的<strong>核心说明文件</strong>，写着这个 Skill 的能力和用法。 开关状态<strong>不会改这个文件</strong>，所以从 <code>.agents</code> 这类目录复制安装的技能 始终保持原样。</p><p><strong>误调用</strong> 你启用了 10 个 Skill，结果它在你只想改个错别字的时候， 顺手调用了发邮件的 Skill 去给你群发邮件——这就叫误调用。 <strong>所以官方建议：只启用当前任务需要的。</strong></p><p><strong>权限申请</strong> Skill 想要访问什么（读文件、发消息、改系统设置），安装时会列给你看。 <strong>安装前一定要看这一项</strong>，这是判断它安不安全的第一道关。</p><p><strong>第三方 Skill</strong> 不是腾讯官方出品、由社区或个人制作的 Skill。质量参差不齐， 有的可能包含恶意代码。<strong>优先用官方推荐的。</strong></p><p><strong>积分消耗</strong> Skill 越复杂、要跑的步骤越多，消耗的积分越多。复杂任务 + 复杂 Skill 是两个大额叠加，用之前留意余额。</p><hr><p><em>下一篇：第 6 章 专家和专家团——给 AI 换个专业身份和协作团队。</em></p>',71)])])}const q=o(e,[["render",d]]);export{b as __pageData,q as default};
